import React, { useState, useMemo } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import './SensorChart.css';
import DatePicker from '../DatePicker/DatePicker';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

const SensorChart = ({ historicalData, startDate, endDate, onTimeRangeChange }) => {
  const [localTimeRange, setLocalTimeRange] = useState({
    startDate,
    endDate
  });
  const [smoothing, setSmoothing] = useState('none'); // none | 5 | 15 (minutes)

  // Форматирование даты для отображения
  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  // Обработчик изменения даты
  const handleDateChange = (type, date) => {
    const newTimeRange = {
      ...localTimeRange,
      [type]: date
    };
    setLocalTimeRange(newTimeRange);
    
    // Если обе даты выбраны, обновляем данные
    if (newTimeRange.startDate && newTimeRange.endDate) {
      onTimeRangeChange(newTimeRange.startDate, newTimeRange.endDate);
    }
  };

  // Вспомогательные функции
  const toLabel = (ts) => ts.replace(' ', 'T'); // локальное время, без 'Z'

  const bucketize = (data, minutes) => {
    if (!Array.isArray(data) || data.length === 0 || minutes === 'none') return data;
    const bucketMs = parseInt(minutes, 10) * 60 * 1000;
    const buckets = new Map();
    data.forEach(({ timestamp, value }) => {
      const d = new Date(toLabel(timestamp));
      const t = d.getTime();
      const key = Math.floor(t / bucketMs) * bucketMs;
      if (!buckets.has(key)) buckets.set(key, { sum: 0, count: 0, ts: key });
      const b = buckets.get(key);
      b.sum += Number(value);
      b.count += 1;
    });
    return Array.from(buckets.values())
      .sort((a, b) => a.ts - b.ts)
      .map((b) => ({ timestamp: new Date(b.ts).toISOString().slice(0, 19).replace('T', ' '), value: b.sum / b.count }));
  };

  const processed = useMemo(() => {
    if (!historicalData) return null;
    const hum = bucketize(historicalData.humidity || [], smoothing);
    const light = bucketize(historicalData.light || [], smoothing);
    const temp = bucketize(historicalData.temperature || [], smoothing);

    // Собираем объединенный и отсортированный список меток времени
    const labelSet = new Set([
      ...hum.map((i) => toLabel(i.timestamp)),
      ...light.map((i) => toLabel(i.timestamp)),
      ...temp.map((i) => toLabel(i.timestamp)),
    ]);
    const labels = Array.from(labelSet).sort((a, b) => new Date(a) - new Date(b));

    // Функция для маппинга значений по метке
    const toMap = (arr) => {
      const m = new Map();
      arr.forEach(({ timestamp, value }) => m.set(toLabel(timestamp), Number(value)));
      return m;
    };
    const humMap = toMap(hum);
    const lightMap = toMap(light);
    const tempMap = toMap(temp);

    const humData = labels.map((l) => (humMap.has(l) ? humMap.get(l) : null));
    const lightData = labels.map((l) => (lightMap.has(l) ? lightMap.get(l) : null));
    const tempData = labels.map((l) => (tempMap.has(l) ? tempMap.get(l) : null));

    return { labels, humData, lightData, tempData };
  }, [historicalData, smoothing]);

  // Подготовка данных для графика (влажность, свет и температура)
  const chartData = useMemo(() => ({
    labels: processed?.labels || [],
    datasets: [
      {
        label: 'Humidity (%)',
        data: processed?.humData || [],
        borderColor: 'rgb(54, 162, 235)',
        backgroundColor: 'rgba(54, 162, 235, 0.15)',
        tension: 0.3,
        borderWidth: 2,
        pointRadius: 0,
        spanGaps: true
      },
      {
        label: 'Light Level',
        data: processed?.lightData || [],
        borderColor: 'rgb(255, 206, 86)',
        backgroundColor: 'rgba(255, 206, 86, 0.15)',
        tension: 0.3,
        borderWidth: 2,
        pointRadius: 0,
        spanGaps: true
      },
      {
        label: 'Temperature (°C)',
        data: processed?.tempData || [],
        borderColor: 'rgb(255, 99, 132)',
        backgroundColor: 'rgba(255, 99, 132, 0.15)',
        tension: 0.3,
        borderWidth: 2,
        pointRadius: 0,
        spanGaps: true
      }
    ]
  }), [processed]);

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
        labels: {
          font: {
            size: 12
          }
        }
      },
      title: {
        display: true,
        text: historicalData 
          ? `График показателей с ${localTimeRange.startDate.toLocaleDateString()} по ${localTimeRange.endDate.toLocaleDateString()}`
          : 'Загрузка данных...',
        font: {
          size: 16
        }
      },
    },
    scales: {
      x: {
        ticks: {
          callback: function(value) {
            const label = this.getLabelForValue(value);
            const date = new Date(label);
            return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
          },
          maxRotation: 0,
          autoSkip: true
        }
      },
      y: {
        beginAtZero: false,
        ticks: {
          precision: 0
        }
      }
    }
  };

  return (
    <div className="sensor-chart-container">
      <div className="chart-controls">
        <DatePicker
          selected={localTimeRange.startDate}
          onChange={(date) => handleDateChange('startDate', date)}
          selectsStart
          startDate={localTimeRange.startDate}
          endDate={localTimeRange.endDate}
          maxDate={localTimeRange.endDate}
          placeholderText="Начальная дата"
        />
        <DatePicker
          selected={localTimeRange.endDate}
          onChange={(date) => handleDateChange('endDate', date)}
          selectsEnd
          startDate={localTimeRange.startDate}
          endDate={localTimeRange.endDate}
          minDate={localTimeRange.startDate}
          maxDate={new Date()}
          placeholderText="Конечная дата"
        />
        <div className="chart-smoothing">
          <label>
            Сглаживание:
            <select value={smoothing} onChange={(e) => setSmoothing(e.target.value)}>
              <option value="none">Нет</option>
              <option value="5">5 минут</option>
              <option value="15">15 минут</option>
            </select>
          </label>
        </div>
      </div>
      
      <div className="sensor-chart">
        {historicalData ? (
          <Line options={options} data={chartData} />
        ) : (
          <div className="loading-message">Загрузка данных...</div>
        )}
      </div>
    </div>
  );
};

export default SensorChart;
